var id=@get:{id};
var taga = new String(java.getString("class.cartoon_catalog cartoon_list@tag.ul@tag.a@text&&class.cartoon_catalog cartoon_list@tag.ul@tag.a@href",false)).trim().split(/\n/);
var len = taga.length/2;
var list = [];
for(var i = 0; i < len; ++i){
    list.push({text : taga[i].trim(), href: taga[i+len].trim()});
}
var page = 2;
var json;
while(page>0){
    json = JSON.parse(java.postForm("https://m.manmanapp.com/works/comic-list-ajax.html","id="+id+"&sort=0&page="+page));
    if(json.code == 0) break;
    json.data.forEach(function(data){
        list.push({text : data.title, href: "https://m.manmanapp.com/comic/detail-"+data.id+".html"});
    });
    page++;
}
list
