@js:
var chapters = JSON.parse(result).data.comic_chapter;
for(var i = 0; i < chapters.length; i++) {
	if (String(chapters[i].chapter_id) == "@get:{chapter_id}") {
    	var domain = chapters[i].chapter_domain;
		var path = chapters[i].rule;
    	var pn =  parseInt(chapters[i].end_num - chapters[i].start_num + 1);
		break;
	}
}
var host = "https://" + domain + path.split("$$")[0];
var ext = path.split("$$")[1];
var piclist = new Array(pn);
for (var i = 0; i < pn; i++) {
	piclist[i] = host + (i + 1) + ext + "-kaimh.middle.webp";
}
piclist@Header:{Referer:thisPage}

