   var str = result.match(/chapterImages = \[(.*)\]/)[1];
   var sign = result.match(/sign = \'(.*)\'/)[1];
   var list = str.replace(/\"|\\/g,"").split("\,");
   var url = result.match(/chapterImageHost\s*=\s*\"(.*?)\"/)[1];
    var piclist = new Array([list.length]);
    for (var i = 0; i < list.length; i++) {
        piclist[i] = url + list[i]+"?sign="+sign;
    }

piclist


