$function getImgList(){
var urlArr=/manhua\/(\d+)\/(\d+).html/.exec(baseUrl);
var str=java.ajax("https://m.qimiaomh.com/Action/Play/AjaxLoadImgUrl?did="+urlArr[1]+"&sid="+urlArr[2]);
var json=JSON.parse(str);
return json. listImg;
}

