@js:
eval(result.match(/var chapterImages.*chapterPath = "([^"]*?)";/)[0]);
var host = "http://img.zzszs.com.cn";
var piclist = new Array();
for (let i in chapterImages) {
  if (chapterImages[i].match(/https?:\/\/(images.dmzj.com|imgsmall.dmzj.com)/i)) {
    piclist[i] = host+"/showImage.php?url="+encodeURI(chapterImages[i]).replace(/\/images\/comic\/\d+\/\d+\//,'');
  } else if (chapterImages[i].match(/^[a-z]\//i)) {
    piclist[i] = host+"/showImage.php?url="+encodeURI("https://images.dmzj.com/"+chapterImages[i]);
  } else if (chapterImages[i].match(/^(http:|https:|ftp:|^)\/\//i)) {
    piclist[i] = chapterImages[i];
  } else {
    piclist[i] = host+chapterImages[i];
  }
}
piclist

$function getImgList() {
    var str = html.match(/(var qTcms_Cur=[\S\s]+var qTcms_S_show_1=.*?;)/);
    eval(str[1]);
    var list = java.atob(qTcms_S_m_murl_e).split("\\$qingtiandy\\$");
    var piclist = new Array([list.length]);
    for (var i = 0; i < list.length; i++) {
        var v = list[i];
        var s = v;
        if (v.substring(0, 1) == "/") {
            s = qTcms_m_weburl + s;
        } else {
            if (qTcms_Pic_m_if != "2") {
                v = v.replaceAll("\\?", "a1a1");
                v = v.replaceAll("&", "b1b1");
                v = v.replaceAll("%", "c1c1");
                var m_httpurl = "";
                if (typeof(qTcms_S_m_mhttpurl) != "undefined") m_httpurl = java.atob(qTcms_S_m_mhttpurl);
                s = qTcms_m_indexurl + "statics/pic/?p=" + escape(v) + "&wapif=1&picid=" + qTcms_S_m_id + "&m_httpurl=" + escape(m_httpurl);
            } else {
                s = s.replace("http:", "");
                s = s.replace("https:", "");
            }
        }
        piclist[i] = s;
    }
    return piclist;
}@Header:{Referer:thisPage}

