        if (filename.match(/^https?:\/\/(images.dmzj.com|imgsmall.dmzj.com)/i)) return host+'/showImage.php?url='+encodeURI(filename);
		if (filename.match(/^[a-z]\//i)) return host+'/showImage.php?url='+encodeURI("https://images.dmzj.com/"+filename);
        if (filename.match(/^(http:|https:|ftp:|^)\/\//i)) return filename;
        filename = chapterPath.trim('/') + '/' + filename;
        return host + '/' + filename;
    }

function getImgList(){
    eval(html.match(/var chapterImages.*chapterPath = "([^"]*?)";/)[0]);

var decryptedStr=java.fns.AES_Decrypt(chapterImages, {
	key:"123456781234567G",
	iv:"ABCDEF1G34123412"
}, true);
chapterImages = JSON.parse(decryptedStr.toString());
if(chapterImages[0].substr(0,4)=='http'&&chapterImages[0].indexOf('dmzj.com')==-1) {
return chapterImages;
}
	return chapterImages.map(function(image){
return getChapterImage(image,chapterPath);
});
}@Header:{Referer:host}

$function getImgList(){
    var node = html.match(/node="(\d+?)"/)[1];
    var count = html.match(/count="(\d+?)"/)[1];
    var did = html.match(/did="(\d+?)"/)[1];
    var piclist = new Array(count);
    for (var i=0; i<count; i++){
        piclist[i] = "http://www.damotu.com/image/"+(i+1)+"-"+did+"-"+node+".htm";
    };
    return piclist;
}@Header:{Referer:thisPage}

