$function getImgList() {
  var str = html.match(/chapterImages\s*=\s*\[(.*?)\]/)[1];
  var path = html.match(/chapterPath\s*=\s*"(.*?)"/)[1];
  var list = str.replace(/"/g,"").replace(/\\/g,"").replace(/\//g,"/").split(",");
  var piclist = new Array([list.length]);
  for (var i = 0; i < list.length; i++) {
    piclist[i] = list[i].indexOf('http')==0?list[i]:("http://res.mhkan.com/"+path+list[i]);
  }
  return piclist;
}

