@js:var str=baseUrl.match(/\d+\/\d+/);
var pn=result.match(/(\d+)頁<\/h1>/)[1];
var piclist=new Array(pn);
for(var i=0;i<pn;i++){
piclist[i]='http://fcache.someou.com/Uploads/files/'+str+'/'+(Array(3).join(0) + (i+1)).slice(-3)+'.jpg'
}
piclist

@js:var host="https://www.magabao.com/g.php?";
var cha=result.match(/chapterId: '(.*?)'/)[1];
var img=result.match(/images: \[(.*?)\]/)[1].replace(/'/g,'').split(",");
var piclist=new Array(img.length);
for(var i=0;i<img.length;i++){
piclist[i]=host+cha+'/'+img[i];
}
piclist

