$function getImgList(){
var img_str = html.match(/img_arr=eval."([^"]+)"/)[1].match(/http[^']+/g);
var img = eval(img_str);
var piclist = new Array([img.length]);
for (var i = 0; i < img.length; i++){
piclist[i] = img[i];
}
return piclist;
}

