$function getImgList() {
    var list = html.match(/(\\\/sinmh)?\\\/comic[\\\/\d\w]+\.jpg/g);
    var url = "http://ccimg.ufo001.com:8088";
    var piclist = new Array([list.length]);
    for (var i = 0; i < list.length; i++) {
        piclist[i] = url + list[i].replace(/\\/g, '');
    }
    return piclist;
}

