var str = result.match(/picTree = \[(.*?)\]/);
var host = result.match(/pic_base = '([^']+)'/)[1];
var list = str[1].replace(/\\|"/g,'').split(",");
var piclist = new Array();     
for (let i in list) {   
  piclist[i] = host + list[i];        
}       
piclist

