$function getImgList() {     
var str = html.match(/z_img=\'\[(.*?)\]/);
var host="https://img.detatu.com/"/*html.match(/"images":\s*\["(.*?)"\]/)[1]*/.split("/");
host=host[0]+"//"+host[2]+'/';
var list = str[1].match(/[^\"]{10,}/g);
var piclist = new Array([list.length]); 
  if(str[1].match(/http/)){
for (var i = 0; i < list.length; i++) {   
piclist[i] = list[i].replace(/\\\//g,"/");}    
}   
else{for (var i = 0; i < list.length; i++) {   
piclist[i] = host + list[i].replace(/\\\//g,"/");}
}
return piclist;    
}

$function getImgList(){
    var p = "chapterImages = \\[(.*?)\\]";
    var p1 = "chapterPath = \"(.*?)\"";
    var chapterPath  = html.match(p1)[1];
    var path = html.match(p)[1].replace(/\"/g, "").split(",");
    var piclist = new Array([path.length]);
    for (var i = 0; i < path.length; i++) {
        piclist[i] = "https://img001.pkqiyi.com/"+chapterPath + path[i];
piclist[i]=piclist[i].replace(/\\/g,'');
    }
    return piclist;
}

