$function getImgList() {
    var str = html.match(/(var qTcms_Cur=[\S\s]+var qTcms_S_show_1=.*?;)/);
    eval(str[1]);
    var list = java.atob(qTcms_S_m_murl_e).split("\\$qingtiandy\\$");
    var piclist = new Array([list.length]);
    for (var i = 0; i < list.length; i++) {
        var v = list[i];
        var s = v;
        if (v.substring(0, 1) == "/") {
            s = qTcms_m_weburl + s;
        } else {
            if (qTcms_Pic_m_if != "2") {
                v = v.replaceAll("\\?", "a1a1");
                v = v.replaceAll("&", "b1b1");
                v = v.replaceAll("%", "c1c1");
                var m_httpurl = "";
                if (typeof(qTcms_S_m_mhttpurl) != "undefined") m_httpurl = java.atob(qTcms_S_m_mhttpurl);
                s = qTcms_m_indexurl + "statics/pic/?p=" + /*escape*/encodeURIComponent(v) + "&picid=" + qTcms_S_m_id + "&pinyin=" + qTcms_S_titlepinyin+ "&m_httpurl=" + encodeURIComponent(m_httpurl)+'&fenye=0';
if(s.indexOf("/")==0){s='http://www.manhuatt.com'+s;}
            } else {
                s = s.replace("http:", "");
                s = s.replace("https:", "");
            }
        }
        piclist[i] = s;
    }
    return piclist;
}@Header:{Referer:thisPage}

