sources.ruleBookContent:
@js:
var images=java.getString('$..image',true);
var cdn=java.getString('$.data.cdn',false);
images.map(function(item){return cdn+item});

$function getImgList() {
    var str = html.match(/(var IMAGE_LIST_URL = \[.*?\];)/);
    eval(str[1]);
    var list = IMAGE_LIST_URL;
     var piclist = new Array([list.length])
    for (var i = 0; i < list.length; i++) {
        piclist[i] = list[i].url;
    }
    return piclist;
}

$function getImgList() {
  var chapters = JSON.parse(html).data.comic_chapter;
  var chapter;
  for (var i=0; i<chapters.length; i++) {
    if (String(chapters[i].chapter_id) == "@get:{chapter_id}") {
      chapter = chapters[i];
      break;
    }
  }

  var path = chapter.rule;
	var host = "https://mhpic.cnmanhua.com" + path.split("$$")[0];
	var ext = path.split("$$")[1];
  var pn = parseInt(chapter.end_num-chapter.start_num+1);
  var piclist = new Array(pn);
  for (var i = 0; i < pn; i++) {
		piclist[i] = host+(i+1)+ext+"-mht.high.webp";
	}
  return piclist;
}@Header:{Referer:host}

