@js:
var str = result.match(/var chapterImages = \[(.*?)\];/)[1];
var list = str.replace(/"|\\/g,"").split(/,/);
var path = result.match(/var chapterPath = "(.*?)";/)[1];
var host = result.match(/var pageImage = "(.*?)";/)[1];
var obj=host.split("/");
host=obj[0]+'//'+obj[2]+'/';
var piclist = new Array();
for (var i=0; i<list.length; i++) {
  if (list[i].match(/^https?:\/\/(images.dmzj.com|imgsmall.dmzj.com)/i)) {
    piclist[i] = host+"showImage.php?url="+encodeURI(list[i]);
  } else if (list[i].match(/^[a-z]\//i)) {
    piclist[i] = host+"showImage.php?url="+encodeURI("https://images.dmzj.com/"+list[i]);
  } else if (list[i].match(/^(http:|https:|ftp:|^)\/\//i)) {
    piclist[i] = list[i];
  } else if (list[i].match(/^(\/|images?)/i)) {
    piclist[i] = host+list[i].replace(/(^\/*)/,"");
  } else {
    piclist[i] = host+path.replace(/(^\/*)|(\/*$)/,"")+"/"+list[i].replace(/(^\/*)/,"");
  }
}
