Promise(function (rv, rj) {
    var key = baseUrl.match(/#key=(.*?)$/);
    if (key) {
        key = decodeURIComponent(key[1]);
    }
    console.log('key=' + key);
    var jsonFileUrl = (result.match(/jsonFileUrl\s*=\s*'(.*?)';/) || result.match(/jsonFileUrl\s*:\s*\["(.*?)"\]/))[1];
    jsonFileUrl = jsonFileUrl.replace(/\\/g, '');
    jsonFileUrl = java.getdirecturl(baseUrl, jsonFileUrl);
    fetch(jsonFileUrl).then(function(x){return x.text()}).then(function (rs) {
        try {
            var json = JSON.parse(rs);
            json = Object.values(json);
            if (key != undefined) {
                json=json.filter(function (item) {
                    return item.meta.title.indexOf(key) != -1
                })
            }
            rv(json)
        } catch (e) {
            rj(e)
        }
    }).catch(rj);
})

