result=java.getString('$.Sources..SourceUrl',true,result);
console.error('fuccc'+JSON.stringify(result))
var url;
try{
result.forEach(function(item){
    if(url) return;
    if(item.indexOf("https://www.hisoman.com")==0){
        url=item.replace('https://www.hisoman.com/comic.html?','https://api.hisoman.com/soman.ashx?action=getsomancomicdetail2&').split('&source=')[0];
    }
})
}catch(e){}
