sources.ruleChapterList:
@js:
var c=java.getString('-a.chapteritem',true,result)||[];
var out=[];
if(c.length){
c.forEach(function(item){
out.push({
title:$(item).text(),
href:$(item).attr('href')
})
})
}else{
console.error(result)
var c=java.getString('$.Comics.*',true,result)||[];
c.forEach(function(item){
var group=item.Source;
(item.Chapters||[]).forEach(function(citem){

out.push({
title:citem.Name,
href:citem.Url,
group:group
})

})

})

}
