var params = result.match(/params = '([^']+)'/)[1];
function decryptParams(encryptedParams) {
 var CryptoJS=java.fns.CryptoJS;
  var parsedData = CryptoJS.enc.Base64.parse(encryptedParams);
  var iv = CryptoJS.lib.WordArray.create(parsedData.words.slice(0, 4)); 
  var encryptedWords = parsedData.words.slice(4);  
  var encryptedHex = CryptoJS.enc.Hex.stringify(CryptoJS.lib.WordArray.create(encryptedWords));
  var key = CryptoJS.enc.Utf8.parse('9S8$vJnU2ANeSRoF'); 
  var decrypted = CryptoJS.AES.decrypt({
    ciphertext: CryptoJS.enc.Hex.parse(encryptedHex)
  }, key, { iv: iv });
 var decryptedText = decrypted.toString(CryptoJS.enc.Utf8);
  var decryptedJson = JSON.parse(decryptedText);
  return decryptedJson.images;
}
var img = String(decryptParams(params)).replace(/\,/g,'\n');
img.split('\n').map(function(item){return java.getdirecturl('https://img1.baipiaoguai.org/',item)})

