function imgurl(url,isTrim) {
    var handle = function (item) {
        var imghost='mwfimsvfast22.cc';
        var url="https://"+imghost;
        item=java.getdirecturl(url,item);
		var uhost=(item.match(/\/\/(.*?)\/static\//)||[])[1];
        if(uhost) item=item.replace(uhost,imghost);
        if(isTrim) item=item.trim().replace(/\?v=\d+$/,'');
        if(item==url) return '';
        return item
    }
    if (typeof (url) == 'object' && !isNaN(url.length)) {
        url = url.map(function (item) {
            return handle(item)
        })
    } else if (typeof (url) == 'string') {
        url = handle(url)
    }
    return url
}

