function handle(result){
    var out;
    var encryptedPhotos = (result.match(/encryptedPhotos\s*=\s*'(.*?)'/)||[])[1];
    var issupport;
    try{
        issupport=(java.getHostObj('App')||{}).versionCode>230226;
    }catch(e){}
    if(encryptedPhotos){
        try{
            var key=result.match(/["|']([a-zA-Z0-9]{16})["|']/)[1];
            var decryptedPhotos=java.fns.AES_Decrypt(encryptedPhotos, {key:key,iv:key}, true);
            var photo_version=(result.match(/photo_version\s*=\s*\'(\d+)\'/)||[])[1]||"20220724";
            out=JSON.parse(decryptedPhotos).map(function(item){
                if(issupport){
                    return item.img_url+'?v='+photo_version+'#__base64__:'+btoa(JSON.stringify({noPage:true,decrypt:{cipher:"AES/CBC/PKCS7Padding",key:'my2ecret782ecret',iv:'my2ecret782ecret'}}))
                }else{
                    return item.img_url+'?v='+ photo_version + '#jiami'
                }
            });
            out=imgurl(out);
        }catch(e){}
        return out;
    }
    try{
        var rarr = java.getString('#cp_img img[data-r-src]@data-r-src', true, result) || [];
        if (rarr.length) {
            out = rarr.map(function (item) {
                if(issupport){
                    return item+'#__base64__:'+btoa(JSON.stringify({noPage:true,decrypt:{cipher:"AES/CBC/PKCS7Padding",key:'my2ecret782ecret',iv:'my2ecret782ecret'}}));
                }
                return item + '#jiami'

            })
        } else {
            out = java.getString('.content-img:not(.lazy_img)@src&&.content-img.lazy_img@data-original', true, result)
        }
        out=imgurl(out);
    }catch(e){}
    return out;
}
function getHeader(resHeader) {
    var headers = resHeader || {};
    console.log(headers);
    if (!headers["Set-Cookie"]) {
        try {
            if (headers && headers["set-cookie"]) {
                if (typeof (headers["set-cookie"]) == "string") {
                    headers["set-cookie"] = [headers["set-cookie"]];
                }
                headers["Set-Cookie"] = headers["set-cookie"].map(function (item) {
                    return item.split(";")[0];
                });
            }
        } catch (e) { }
    } else if (typeof (headers["Set-Cookie"]) == "string") {
        headers["Set-Cookie"] = [headers["Set-Cookie"]];
    }
    var cookie = (headers["Set-Cookie"] || []).join(";");
    baseHeader.cookie = '';
    if (cookie) baseHeader.cookie = cookie;
    return baseHeader;
}
var out=handle(result)|| [];
if (out.length == 0 || result.indexOf('如果你看到这个讯息')!=-1/*out.length == 3*/) {
    var baseHeader=baseHeader||{};
    // console.log(baseHeader);
    // if(out.length == 0){
    //     baseHeader=getHeader(resHeader) || {};
    // }else{
        baseHeader.cookie='';
        console.log(baseHeader);
    // }

    out=new Promise(function(resolve,reject){
        try{
            java.curl({
                url:baseUrl,
                header:baseHeader,
                nativeres:true,
                login:false,
                //webview:!!Object.keys(baseHeader).length
            }).then(function(res){
                try{
                    // var out=handle(res.result) || [];
                    // if (out.length == 0) {

                        baseHeader=getHeader(res.header) || {};

                        java.curl({
                            url:baseUrl,
                            header:baseHeader,
                            nativeres:true,
                            login:false,
                            //webview:!!Object.keys(baseHeader).length
                        }).then(function(res){
                            try{
                                var out=handle(res.result);
                                resolve(out);
                            }catch(e){
                                reject();
                            }
                        }).catch(reject);
                    // }else{
                    //     resolve(out);
                    // }
                }catch(e){
                    reject();
                }
            }).catch(reject)
        }catch(e){
            reject();
        }        
    });

}
