if(baseUrl.indexOf('#jiami')==-1){
    baseUrl
}else{
    fetch(baseUrl,{
        method: 'get',
        responseType: 'arraybuffer'
    }).then(function(res){
        return res.arrayBuffer()
    }).then(function(arraybuffer){
        var b64=java.fns.CryptByte("decrypt",java.fns.arrayBufferToBase64(arraybuffer),{type:"AES",mode:"CBC",padding:"Pkcs7",key:'my2ecret782ecret',iv:'my2ecret782ecret'})
        return 'data:image/webp;base64,'+b64;
    })
}

