        if(isTrim) item=item.trim().replace(/\?v=\d+$/,'');
        if(item==url) return '';
        return item
    }
    if (typeof (url) == 'object' && !isNaN(url.length)) {
        url = url.map(function (item) {
            return handle(item)
        })
    } else if (typeof (url) == 'string') {
        url = handle(url)
    }
    return url
}

