function getHostByRace(hostList) {
  return new Promise(function (resolve, reject) {
    try {
      var acList = [];
      var errorNum = 0;
      var callback = function (host) {
        while (acList.length) {
          var ac = acList.shift();
          try {
            ac.abort();
          } catch (e) {}
        }
        resolve(host);
      };
      hostList.map(function (host) {
        var ac;
        try {
          ac = new AbortController();
        } catch (e) {
          ac = {
            signal: undefined,
            abort: function () {},
          };
        }
        acList.push(ac);
        var url = "https://" + host;
        fetch(url, {
          method: "head",
          mode: "no-cors",
          signal: ac.signal,
        })
        .then(function () {
          callback(host);
        })
        .catch(function (e) {
          if (e.toString().indexOf("403") != -1) {
            callback(host);
          } else {
            errorNum++;
            if (errorNum == hostList.length) {
              reject();
            }
          }
        });
      });
    } catch (e) {
      reject();
    }
  });
}
