      var errorHandle=function(e){
        if(a.length>0){
          handle();
        }else{
          reject(e);
        }
      }
      var url=getdirecturl("http://"+a.pop(),path);
      java.curl({
        url: url,
        header: f,
        nativeres: true
      }).then(function(res) {
        try{
          res = res.result;
          var data=JSON.parse(res.trim());
          console.log(data);
          var rs=decryptData(data);
          console.log(rs);
		  try{
			var phost=rs.match(/"pic":"https:\\\/\\\/(.*?)\\\/static\\\//)[1];
			if(imageHostList.indexOf(phost)==-1){
				imageHostList.push(phost);
			}
		  }catch(e){}
          getHostByRace(imageHostList).then(function(host){
            rs=setImageHost(rs,host);
