var cid=baseUrl.match(/kanmanhuaIndexSY\/(\d+)/)[1];
var sid=baseUrl.match(/stageIndexSY\/(\d+)/)[1];
//'/KanmanhuaWap/Index/getStageImgArray@stageIndexSY='+cid
'/KanmanhuaH5/index/getComicStageDetailData#stageIndexSY='+cid

var getRndNum = function(n) {
    return Math.floor(Math.random() * n)
}

var doSign = function(n) {
    var a = n + "##" + atob('dmVyb25zbDE5ODMwMTIz')
    var i = java.md5Encode(a);
    return i
}

var e = java.getdirecturl(baseUrl,"/KanmanhuaH5/index/getComicStageDetailData")
, a = getRndNum(9e5)
, o = sid + "##" + a
, s = doSign(o);

var l = "comicindexsy=" + cid + "&stageindexsy=" + sid + "&rndKey=" + a + "&signStr=" + s
    , c = false;
l += "&isAuditingVersion=" + c + "&isClientLogin=" + false;
l += "&username=" + "" + "&password=" + "";
l += "&clientType=2&versionCode=1042&qudaoID=998";
java.curl({
    method:"POST",
    url:e,
    postdata:l,
    postform:true
}).then(function(res){
    var data = JSON.parse(res.result);
    return java.getString('$.stageDetailData.imgArray..imgUrl',true,data);
})

