var params = result.match(/params = '([^']+)'/)[1];

var decrypt=function(encryptedData) {
    var CryptoJS=java.fns.CryptoJS;
    var encryptedDataWithIV = CryptoJS["enc"]["Base64"]["parse"](encryptedData)
        , iv = CryptoJS["lib"]["WordArray"]["create"](encryptedDataWithIV["words"]["slice"](0, 16))
        , encryptedBytes = encryptedDataWithIV["words"]["slice"](4)
        , encryptedHex = CryptoJS["enc"]["Hex"]["stringify"](CryptoJS["lib"]["WordArray"]["create"](encryptedBytes))
        , keyUtf8 = CryptoJS["enc"]["Utf8"]["parse"]("5V&RoR%Jf@pJPydF")
        , decrypted = CryptoJS["AES"]["decrypt"]({
            ciphertext: CryptoJS["enc"]["Hex"]["parse"](encryptedHex)
        }, keyUtf8, {
            iv: iv
        })
        , decryptedText = decrypted["toString"](CryptoJS["enc"]["Utf8"])
        , decryptedArray = JSON["parse"](decryptedText);
    return decryptedArray;
}
var obj=decrypt(params);
var img = obj.chapter_images;
var domain=obj.images_domain;
img.map(function(item){return java.getdirecturl(domain,item)})

