$function getImgList(){
    var p ="eval\\(.*\\)";
    var jseval = html.match(p)[0];
    eval(eval("("+jseval.substring(5,jseval.length-1)+")"));
var list = cInfo.fs;
var piclist=new Array([list.length]);
for (var i = 0; i < list.length; i++) {
        piclist[i] = (list[i].indexOf("http")!=0?"http://imagesold.502215.com":"") + list[i];
    }
   return piclist;
}

