var list = [];
var res = org.jsoup.Jsoup.parse(result);
var arr = res.select("a.fed-btns-info").toArray();
for (var i in arr) {
    var title = arr[i].text();
	if(title.indexOf("当前")==0) continue;
    var chapUrl = arr[i].attr("href").replace("#",'')||baseUrl;
	list.push({
		title:title,
		url:chapUrl
	});
};
