@js:
var srcCode = (result.match(/src\s*=\s*src.substr\(.*?\);/g) || []).join("");
console.log("srcCode:" + srcCode);
java.getString("img.lazy", true, result).map(function (src) {
    try {
        src = $(src).attr('data-original');
        if (srcCode) eval(srcCode);
        console.log(src);
        var strArr = src.split("");
        var len = src.length;
        var json = {
            7: 0x1,
            8: 0x2,
            9: 0x3,
            12: 0x2,
            14: 0x3,
            15: 0x1,
            16: 0x2,
            18: 0x3,
            19: 0x2,
            22: 0x2,
            25: 0x1,
            30: 0x5,
            32: 0x1,
        };
        for (var i in json) {
            var code = strArr[len - i];
            if (code) {
                var num = code.charCodeAt() - json[i];
                strArr[len - i] = String.fromCharCode(num);
            }
        }
        console.log(strArr.join(""))
        var base64 = java.atob(("abcd" + (strArr.join("") + "abcd").replace("abcd", "")).replace("abcd", "")); //var base64 = bs64DeCode(test(x));
        return base64.replace("\ue600", "");
    } catch (e) {
        return '';
    }
});

