var arr = java.getString(".charpetBox@img", true, result);
var oarr = [];
var map = {};
arr.forEach(function (img) {
    var id=$(img).attr('id');
    var url = $(img).attr('data-original');
    if(!map[id]) map[id]=[];
    map[id].push(url);
    oarr=Object.keys(map).map(function(key){
        if(typeof(map[key])=='string'){
            return map[key];
        }else{
            return map[key].join('##');
        }
    });
});
oarr@NoFetch

sources.ruleBookPageContent:
@js:
var o;
var issupport = false;
try {
    var App = java.getHostObj("App") || {};
    var ExView = java.getHostObj("ExView") || {};
    issupport = ExView.versionCode || (App && (App.versionCode || 0) >= 201202);
} catch (e) { }
if (issupport) {
    var imgArr = baseUrl.split("##");
    if (imgArr.length == 1) {
        o = [baseUrl];
    } else {

        function getImage(url) {
            return new Promise(function (resolve, reject) {
                var img = new Image();
                //img.setAttribute("crossOrigin",'Anonymous');
                img.onload = function () {
                    resolve(img);
                }
                img.onerror = function (e) {
                    reject(e);
                }
                img.src = url;
            });
        }
        function mixImage(arr) {
            // var id = "XXCanvas_" + java.md5Encode(baseUrl);
            var canvas;
            if (window.OffscreenCanvas) {
                canvas = new OffscreenCanvas(300, 150);
            } else {
                // canvas = document.querySelector("#" + id);
                // if (canvas) canvas.remove();
                canvas = document.createElement("canvas");
                // canvas.id = id;
                // document.body.appendChild(canvas);
            }
            var ctx = canvas.getContext("2d");
            var w = (function () {
                var out = 0;
                arr.forEach(function (img) {
                    out += img.naturalWidth;
                });
                return out;
            })(); //原始尺寸
            var h = arr[0].naturalHeight;
            canvas.width = w;
            canvas.height = h;
            var x = 0;
            arr.forEach(function (img) {
                var copyW = img.naturalWidth;
                var copyH = img.naturalHeight;
                ctx.drawImage(img, x, 0, copyW, copyH);
                x += copyW;
            });
            if (window.OffscreenCanvas) {
                return canvas
                    .convertToBlob({ type: "image/jpeg", quality: 0.7 })
                    .then(function (blob) {
                        var reader = new FileReader();
                        reader.readAsDataURL(blob);
                        return new Promise(function (resolve, reject) {
                            reader.onloadend = function () {
                                resolve(reader.result);
                            };
                            reader.onerror = reject;
                        });
                    });
            }
            return window.Promise.resolve(canvas.toDataURL("image/jpeg", 0.7));
        }
        o = Promise(function (resolve, reject) {
            window.Promise.all(imgArr.map(function (url) {
                return getImage(url);
            })).then(function (arr) {
                //console.log(arr);
                return mixImage(arr);
            }).then(function (imgUrl) {
                //console.log(imgUrl);
                resolve(imgUrl);
            }).catch(reject);
        });
    }
} else {
    o = [baseUrl];
}
o

