if(baseUrl.indexOf('/en_images/')==-1){
    baseUrl
}else{
function arrayBufferToBase64(buffer) {
	var binary = '';
	var bytes = new Uint8Array(buffer);
	var len = bytes.byteLength;
	for (var i = 0; i < len; i++) {
		binary += String.fromCharCode(bytes[i]);
	}
	return window.btoa(binary);
}
new Promise(function(reslove,reject){
    fetch(baseUrl,{
        method: 'get',
        responseType: 'arraybuffer'
    }).then(function(res){
        return res.arrayBuffer()
    }).then(function(arrayBuffer){
            var iv = arrayBuffer.slice(0, 16);
            var ciphertext = arrayBuffer.slice(16);
            var keyBytes = new TextEncoder().encode('0B6666A0-BB59-1381-B746-a0E4C9AC').slice(0, 32);

            window.crypto.subtle.importKey(
                "raw", keyBytes, { name: "AES-CBC" }, false, ["decrypt"]
            ).then(function(cryptoKey){
                window.crypto.subtle.decrypt(
                    { name: "AES-CBC", iv: new Uint8Array(iv) },
                    cryptoKey,
                    ciphertext
                ).then(function(decryptedBuffer){
                    reslove('data:image/jpeg;base64,'+arrayBufferToBase64(decryptedBuffer));
                });
            });
    }).catch(reject)
})


}

