function crackimg(img) {
    return img + '#__base64__:' + btoa(JSON.stringify({
        "header": {"referer": "https://www.favcomic.xyz/"},
        "handle": "(" + (function(){try{var d=function(buffer,base64Key){var key=CryptoJS.enc.Utf8.parse(atob(base64Key));var bytes=new Uint8Array(buffer);var iv=CryptoJS.lib.WordArray.create(bytes.slice(0,16));var ciphertext=CryptoJS.lib.WordArray.create(bytes.slice(16));var decrypted=CryptoJS.AES.decrypt({ciphertext},key,{iv:iv,mode:CryptoJS.mode.CBC,padding:CryptoJS.pad.Pkcs7});var decryptedWords=CryptoJS.enc.Latin1.stringify(decrypted);var decryptedBytes=new Uint8Array(decryptedWords.length);for(var i=0;i<decryptedWords.length;i++){decryptedBytes[i]=decryptedWords.charCodeAt(i)}return decryptedBytes};var o=new Uint8Array(base64ToUint8Array(result));o=d(o,'NlgrYjYuRT5ic1hifSs9Tg==');callback(arrayBufferToBase64(o))}catch(e){callback()}}).toString() + ")()"
    }))
}

