@js:
var urls=java.getString("[data-original]@data-original",true,result);
var url=urls[0];
var arr=url.split("/0");
var qa=arr[0];
var qh=arr[1];

var getdatas=function(page){
    return fetch(qa+"/"+page+qh,{method: 'head'}).then(function(res){return res.ok});
}
var arr=[];
var findmax=function(page){
    return getdatas(page).then(function(rs){
        if(rs){
            return findmax(page+10)
        }else{
            return page;
        }
    })
}
var findmin=function(page){
    return getdatas(page).then(function(rs){
        if(!rs){
            return findmin(page-1)
        }else{
            return page;
        }
    })
}
if(qh===undefined){
urls
}else{
new Promise(function(resolve,reject){
    try{
        findmax(10).then(function(max){
            findmin(max-1).then(function(min){
                console.log(min);
                var out=[];
                for(var i=0;i<min+1;i++){
                    out.push(qa+"/"+i+qh);
                }
                resolve(out);
            })
        }).catch(reject)
    }catch(e){
        reject(e)
    }
})
}

