var arr=java.getString('div[x-data*="chapters:"]',true,result);
arr.map(function(item){
    var group=$(item).find(".text-lg>div").text();
    var data=$(item).attr("x-data").match(/chapters: (\[.*?\]),/)[1];
    console.log(data);
    return JSON.parse(data).map(function(citem){
        citem.group=group;
        return citem;
    });
});

