$function getImgList(){  
    var str = html.match(/var chapterImages.*];/);
    eval(str[0]);
    var piclist = new Array([chapterImages.length]);
    for (var i = 0; i < chapterImages.length; i++) {
        piclist[i] = "https://res.nbhbzl.com/" + chapterImages[i];
    }
    return piclist;
}

