$function getImgList(){
    var str = html.match(/murl_e=\"(.*?)\"/)[1];
    var list = JsEngine.atob(str).split("\\$qingtiandy\\$");
    return list.map(function(item){return (item.indexOf("http")==0&&item.indexOf("mhpic.")==-1?("https://m.daigege.com/statics/pic/?p="+encodeURIComponent(item)):item)});
