$function getImgList(){
  var str = html.match(/(var mhInfo.*};)/);
  eval(str[0]);
  var host = mhInfo.host;

  parseInt(mhInfo.chapterId) > 542724 ? host = "https://mhreswhm.tgmhfc.uk" : host = "https://mhpic6.kingwar.cn";
  //if(parseInt(mhInfo.chapterId) > 885032) host = "https://qwe123.tgmhfc.uk";
  var piclist = new Array([mhInfo.count]);
  for (var i = 0; i < mhInfo.count; i++) {
    piclist[i] = host+ mhInfo.path+mhInfo.images[i];
  }
  return piclist;
}@Header:{Referer: thisPage}

