$function getImgList(){
 var p1 = "chapter_list_all.\\[(.*?)\\]";
 var p = html.match(p1)[1].replace(/\"/g, "").split(",");
var piclist = new Array([p.length]);
for (var i = 0; i < p.length; i++) {
 piclist[i] = p[i];
}
return piclist;
}

