$function getImgList() {
 var picid=(/qTcms_S_m_id=\"(\d+)\"/.exec(html))||[]; picid=picid[1];  var str = html.match(/murl_e=\"(.*?)\"/)[1];
    var list = JsEngine.atob(str).split("\$qingtiandy\$");

var piclist = new Array([list.length]);        
for (var i = 0; i < list.length; i++) {   
piclist[i] = (list[i].indexOf("http")==0?("http://h.ccshwy.com/statics/pic/?p="+encodeURIComponent(list[i])+"&wapif=1&picid="+picid+"&m_httpurl="):("http://www.ccshwy.com/"+list[i]))  ;        
}       
    return piclist;
}

