var chapterImages=result.match(/chapterImages\s*=\s*\[(.*?)\];/)[1];
chapterImages=JSON.parse('['+chapterImages+']');
var host=result.match(/getCirh\(\)\{return ["|'](.*?)["|'];\}/)[1];
chapterImages.map(function(item){
if(item.indexOf('http://')==0||item.indexOf('https://')==0) return item;
return host+item;
})

